   @for(claim of session.access()?.claims?.testGroupMonitor??[];track $index){<button matButton="outlined" class="monitor-claim" (click)="open(claim)" [attr.data-group]="claim.id"><strong>{{claim.label}}</strong><span>{{claimLabel(claim)}}</span></button>}
  </section>
 }
}

