import {readOriginalPerson} from './original-test-access.js';
import type {OriginalAuthenticationPort} from './original-authentication.js';
import type {OriginalMonitorRepository} from './original-monitor-store.js';
import {formatOriginalMonitorSessionsJson, type OriginalMonitorActor} from './original-monitor-session.js';
import {FirstSliceError} from './first-slice-error.js';

export type OriginalMonitorPort = {
  requireMonitor(input: {token: string; groupKey?: string}): Promise<void>;
  changeLocks(input: {token: string; groupKey: string; locked: boolean; body: unknown}): Promise<void>;
  profile(input: {token: string; profileId: string}): Promise<OriginalMonitorProfile>;
  booklet(input: {token: string; bookletName: string}): Promise<string>;
  sessions(input: {token: string; groupKey?: string}): Promise<string>;
};
export function createOriginalMonitorPort(input: {auth: OriginalAuthenticationPort; repository: OriginalMonitorRepository & Pick<import('./index.js').FirstSliceRepository,'appendOriginalTestLogs'>; now:()=>string; id:()=>string;
  profiles: (actor: OriginalMonitorActor) => Promise<OriginalMonitorProfile[] | undefined>;
  assignedBooklets: (person: ParticipantSession) => Promise<string[]>;
  readBooklet: (scope: {tenantId: string; workspaceId: string}, name: string) => Promise<{xml: string}>;
}): OriginalMonitorPort {
  const actor = async (token: string): Promise<OriginalMonitorActor> => {
    const state = await input.auth.read({token});
    if (state.kind !== 'person' || state.participantSession.originalLoginKey === undefined ||
      !['monitor-group', 'monitor-study'].includes(state.participantSession.originalOperationalMode ?? '')) {
      throw new FirstSliceError(403, 'original_monitor_forbidden', 'A current native monitor is required.');
    }
    const person = state.participantSession;
    return {participantSessionId: person.participantSessionId, tenantId: person.tenantId, workspaceId: person.workspaceId,
      originalLoginKey: person.originalLoginKey!, groupKey: person.groupKey, mode: person.originalOperationalMode as OriginalMonitorActor['mode']};
  };
  return {
    async requireMonitor({token,groupKey}) {const monitor=await actor(token);if(groupKey!==undefined)originalMonitorGroupSelection(monitor,groupKey);},
    async changeLocks({token,groupKey,locked,body}) {
      const monitor=await actor(token);originalMonitorGroupSelection(monitor,groupKey);
      for(const value of originalMonitorLockSelection(body)) {
        const testNumber=originalMonitorLockTestNumber(value);
        const {scope,actorPersonNumber}=await input.repository.changeOriginalMonitorTestLock(monitor,groupKey,testNumber,locked,input.now());
        if(locked)await input.repository.appendOriginalTestLogs(scope,[{participantTestLogId:originalTestLogIdPrefix+input.id(),
          tenantId:scope.tenantId,workspaceId:scope.workspaceId,participantSessionId:scope.participantSessionId,testRunId:scope.testRunId,
          unitKey:null,originalUnitId:null,logKey:'locked by monitor',logContent:actorPersonNumber,timestamp:0,originalTimestamp:0,recordedAt:input.now()}]);
      }
    },
    async profile({token, profileId}) {
      const profiles = await input.profiles(await actor(token));
      if (profiles === undefined) throw new FirstSliceError(409, 'original_monitor_profile_history_unknown', 'The original authored profile is unavailable; import its validated Testtakers XML again.');
      const profile = profiles.find(profile => originalMonitorProfileIdsEqual(profile.id, profileId));
      if (!profile) throw new FirstSliceError(404, 'original_monitor_profile_missing', `Profile not found \`${profileId}\``);
      return structuredClone(profile);
    },
    async booklet({token, bookletName}) {
      const person = await readOriginalPerson(input.auth, token);
      const monitor = ['monitor-group', 'monitor-study'].includes(person.originalOperationalMode ?? '');
      if (!monitor && !(await input.assignedBooklets(person)).some(name => originalParticipantGroupKeysEqual(parseOriginalTestName(name).fileId, bookletName))) {
        throw new FirstSliceError(403, 'original_booklet_forbidden', 'The requested Booklet is not assigned to this person.');
      }
      return (await input.readBooklet(person, bookletName)).xml;
    },
    async sessions({token, groupKey}) {return formatOriginalMonitorSessionsJson(await input.repository.readOriginalMonitorSessions(await actor(token), groupKey));}
  };
}

const enterOperational = async (principal:import('./original-authentication.js').OriginalAuthenticationPrincipal,code:string):Promise<ParticipantSession> => {
  if(!isOriginalOperationalLogin(principal.rosterEntry))throw new Error('An operational principal is required.');
  if(code!=='')throw new FirstSliceError(403,'participant_code_invalid','The operational native Login has no assigned person code.');
  const timestamp=now(),entry=principal.rosterEntry;
  const candidate:ParticipantSession={participantSessionId:idGenerator(),tenantId:principal.workspace.tenantId,workspaceId:principal.workspace.workspaceId,
    contentReleaseId:null,loginKey:entry.loginKey,groupKey:principal.binding.groupKey,originalLoginKey:entry.loginKey,
    originalNameSuffix:'',originalOperationalMode:entry.originalOperationalMode,participantCode:'',status:'signed_in',createdAt:timestamp,
    validUntil:resolveParticipantSessionValidUntil(entry,timestamp)};
  assertParticipantAccessWindow(entry,timestamp,candidate.validUntil);
  const result=await repository.resolveOriginalParticipantSession(candidate,person=>assertParticipantAccessWindow(entry,timestamp,person.validUntil));
  if(!result)throw new FirstSliceError(409,'original_login_scope_changed','The Original login scope changed during authentication.');
  return result.participantSession;
};
const currentOriginalBooklet=async(person:ParticipantSession,fileId:string)=>{
  const current=await workspaceFiles.read(person);
  const booklet=current.compilation?.runtimeSnapshot?.bookletEntries.find(entry=>sameOriginalTestName(entry.bookletKey,fileId));
  if(!booklet)throw new FirstSliceError(404,'original_booklet_unavailable','No Booklet with id `'+fileId+'` found on workspace `'+person.workspaceId+'`!');
  const release=await requireParticipantContentRelease(person);return{booklet,contentReleaseId:release.contentReleaseId};
};
const materializeOriginalMonitor=async(actor:ParticipantSession)=>{
  if(actor.originalOperationalMode!=='monitor-group'&&actor.originalOperationalMode!=='monitor-study')return;
  const current=await operationalDefinition(actor,actor.originalLoginKey!);
  const binding=(await repository.listOriginalLoginBindingsByWorkspace(actor.tenantId,actor.workspaceId)).find(row=>row.loginKey===actor.originalLoginKey);
  if(!current||!binding||!await activeNativeWorkspace(actor)||current.definition.originalOperationalMode!==actor.originalOperationalMode||
    !sameOriginalTestName(current.definition.groupKey,actor.groupKey)||!sameOriginalTestName(binding.groupKey,actor.groupKey)){
    throw new FirstSliceError(409,'original_login_scope_changed','The Original monitor scope changed during authentication.');
  }
  // A reimport can retain an older ordinary roster entry for a current
  // operational Login. Never materialize it as a dependent and demote its
  // authenticated monitor person (including a different study monitor).
  const operationalKeys=new Set((await repository.listOriginalOperationalLoginsByWorkspace(actor.tenantId,actor.workspaceId)).map(login=>login.loginKey));
  const members=(await repository.listParticipantRosterEntriesByWorkspace(actor.tenantId,actor.workspaceId)).filter(member=>
    !operationalKeys.has(member.loginKey)&&originalMonitorable(member)&&!participantExecutionModeDefinitions[member.executionMode!].alwaysNewSession&&
    (actor.originalOperationalMode==='monitor-study'||sameOriginalTestName(member.groupKey,actor.groupKey)));
  for(const member of members){
    let memberBinding=(await repository.listOriginalLoginBindingsByWorkspace(actor.tenantId,actor.workspaceId)).find(row=>row.loginKey===member.loginKey);
    if(!memberBinding){
      const group=await repository.getOrCreateOriginalParticipantGroup({tenantId:actor.tenantId,workspaceId:actor.workspaceId,groupKey:member.groupKey,groupLabel:member.groupLabel??'',createdAt:now()});
      if(!group)throw new FirstSliceError(409,'original_login_scope_changed','The Original member scope changed during registration.');
      memberBinding=await repository.bindOriginalLoginGroup({tenantId:actor.tenantId,workspaceId:actor.workspaceId,loginKey:member.loginKey,groupKey:member.groupKey,groupSnapshotKey:group.groupKey,authenticatedAt:now()})??undefined;
    }
    if(!memberBinding)throw new FirstSliceError(409,'original_login_scope_changed','The Original member scope changed during registration.');
    // Private recoverable capabilities are reused and never returned to a monitor.
    for(const kind of ['login','group'] as const)for(let attempt=0;attempt<32;attempt++){
      try{const capability=await repository.getOrCreateOriginalSessionToken({tenantId:actor.tenantId,workspaceId:actor.workspaceId,kind,subjectKey:kind==='login'?member.loginKey:memberBinding.groupSnapshotKey,token:createOriginalSessionToken(),createdAt:now()});
        if(!capability)throw new FirstSliceError(409,'original_login_scope_changed','The Original member scope changed during registration.');break;
      }catch(error){if(!(error instanceof OriginalSessionTokenCollisionError)||attempt===31)throw error;}
    }
    for(const[code,assignments]of collectOriginalParticipantAssignments(getOriginalParticipantBookletAssignments(member))){
      const timestamp=now();
      const resolved=await repository.resolveOriginalParticipantSession({participantSessionId:idGenerator(),tenantId:actor.tenantId,workspaceId:actor.workspaceId,contentReleaseId:null,
        loginKey:member.loginKey,originalLoginKey:member.loginKey,originalNameSuffix:createOriginalPersonNameSuffix(code,false),participantCode:code,groupKey:memberBinding.groupKey,
        executionMode:member.executionMode,status:'signed_in',createdAt:timestamp,validUntil:resolveParticipantSessionValidUntil(member,timestamp)});
      if(!resolved||typeof resolved.participantSession.originalNameSuffix!=='string')throw new FirstSliceError(409,'original_person_history_unknown','The Original dependent person identity is unavailable.');
      const person=resolved.participantSession;
      // Source allowExpired=true, forceUpdateToken=REDACTED This conditional
      // write never replaces an active bearer from a concurrent human login.
      if(!await repository.ensureOriginalPersonCredential({...person,originalLoginKey:person.originalLoginKey!,originalNameSuffix:person.originalNameSuffix!,
        tokenHash:hashOriginalSessionToken(createOriginalSessionToken()),updatedAt:now()}))throw new FirstSliceError(409,'original_login_scope_changed','The Original member scope changed during registration.');
      for(const assignment of assignments)await createOriginalPersonTest({repository,now,id:idGenerator,currentBooklet:currentOriginalBooklet},person,assignment.assignmentKey,true);
    }
  }
};
